function cookies(req) {
  return Object.fromEntries((req.headers.cookie || '').split(';').filter(Boolean).map(part => { const i = part.indexOf('='); return [part.slice(0, i).trim(), decodeURIComponent(part.slice(i + 1).trim())]; }));
}
function setSessionCookie(res, token, maxAge) {
  res.setHeader('Set-Cookie', [`${COOKIE}=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}${production ? '; Secure' : ''}`, `mafia_csrf=${encodeURIComponent(res.locals.csrfToken)}; Path=/; SameSite=Lax; Max-Age=${maxAge}${production ? '; Secure' : ''}`]);
}
function clearSessionCookie(res) { res.setHeader('Set-Cookie', [`${COOKIE}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${production ? '; Secure' : ''}`, `mafia_csrf=; Path=/; SameSite=Lax; Max-Age=0${production ? '; Secure' : ''}`]); }

async function requireAuth(req, res, next) {
  try {
    const token = cookies(req)[COOKIE];
    if (!token || token.length < 40 || token.length > 120) throw fail(401, 'unauthorized', 'Sign in to continue.');
    const [rows] = await getPool().execute('SELECT s.id AS session_id, s.user_id, s.csrf_hash, s.expires_at, u.username, u.email, u.avatar, u.account_status FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.revoked_at IS NULL AND s.expires_at > UTC_TIMESTAMP(3) LIMIT 1', [hash(token)]);
    if (!rows.length || rows[0].account_status !== 'active') throw fail(401, 'unauthorized', 'Your session is invalid or expired.');
    req.user = { id: rows[0].user_id, username: rows[0].username, email: rows[0].email, avatar: rows[0].avatar };
    req.authSession = rows[0];
    if (!['GET','HEAD','OPTIONS'].includes(req.method)) {
      const supplied = req.get('x-csrf-token') || '';
      if (!supplied || supplied !== cookies(req).mafia_csrf) throw fail(403, 'csrf_failed', 'Refresh your session and try again.');
      const actual = Buffer.from(hash(supplied));
      const expected = Buffer.from(rows[0].csrf_hash);
      if (actual.length !== expected.length || !timingSafeEqual(actual, expected)) throw fail(403, 'csrf_failed', 'Refresh your session and try again.');
    }
    next();
  } catch (err) { next(err); }
}
const wrap = fn => (req,res,next) => Promise.resolve(fn(req,res,next)).catch(next);
function persistentLimiter({windowMs,limit,scope}){return wrap(async(req,res,next)=>{const start=new Date(Math.floor(Date.now()/windowMs)*windowMs);const bucket=hash(`${scope}:${req.ip||'unknown'}`);await getPool().execute('INSERT INTO rate_limit_buckets (bucket_key,window_start,hits) VALUES (?,?,1) ON DUPLICATE KEY UPDATE hits=IF(window_start<VALUES(window_start),1,hits+1),window_start=GREATEST(window_start,VALUES(window_start))',[bucket,start]);const [[row]]=await getPool().execute('SELECT hits FROM rate_limit_buckets WHERE bucket_key=?',[bucket]);if(row.hits>limit){res.set('Retry-After',String(Math.max(1,Math.ceil((start.getTime()+windowMs-Date.now())/1000))));throw fail(429,'rate_limited','Too many requests. Try again later.');}next();});}
