const registerSchema = z.object({ username:z.string().trim().min(2).max(24).regex(/^[\p{L}\p{N}_-]+$/u), email:z.string().trim().email().max(254).transform(v=>v.toLowerCase()), password:z.string().min(10).max(128) }).strict();
