const roleIds=['civilian','mafia','don','sheriff','doctor','detective','jailor','prostitute','vagabond','maniac'];
const roomSchema = z.object({ name:z.string().trim().min(3).max(40), visibility:z.enum(['public','private']).default('public'), mode:z.enum(['classic','custom']).default('classic'), language:z.enum(['EN','RO']).default('EN'), maxPlayers:z.number().int().min(6).max(12).refine(n=>[6,8,10,12].includes(n)), password:z.string().max(128).optional(), settings:z.object({ minPlayers:z.number().int().min(6).max(12).default(6), allowAbstain:z.boolean().default(false), revealVotes:z.boolean().default(false), chatDuringVoting:z.boolean().default(false), daySeconds:z.number().int().min(60).max(60).default(60), nightSeconds:z.number().int().min(30).max(300).default(60), voteSeconds:z.number().int().min(15).max(120).default(30), roleRevealSeconds:z.number().int().min(5).max(10).default(8), customRoles:z.array(z.enum(roleIds)).max(12).optional() }).default({}) }).strict().superRefine((v,ctx)=>{if(v.visibility==='private'&&(!v.password||v.password.length<6))ctx.addIssue({code:'custom',message:'Private rooms require a password of at least 6 characters.',path:['password']});if(v.settings.minPlayers>v.maxPlayers)ctx.addIssue({code:'custom',message:'Minimum players cannot exceed maximum players.',path:['settings','minPlayers']});if(v.mode==='custom'&&!v.settings.customRoles?.length)ctx.addIssue({code:'custom',message:'Choose a role distribution for Custom mode.',path:['settings','customRoles']});if(v.settings.customRoles?.length&&(v.mode!=='custom'||v.settings.customRoles.length!==v.settings.minPlayers||v.settings.minPlayers!==v.maxPlayers||!v.settings.customRoles.some(r=>['mafia','don'].includes(r))||!v.settings.customRoles.some(r=>!['mafia','don','maniac'].includes(r))))ctx.addIssue({code:'custom',message:'Custom roles must match the fixed player count and include Mafia and Town.',path:['settings','customRoles']});if((v.settings.customRoles?.filter(r=>r==='don').length||0)>1||(v.settings.customRoles?.filter(r=>r==='sheriff').length||0)>1)ctx.addIssue({code:'custom',message:'A match can contain at most one Don and one Sheriff.',path:['settings','customRoles']});});
const uuidParam = z.string().uuid();
function validateParam(name) { return (req,res,next)=>{const v=uuidParam.safeParse(req.params[name]);if(!v.success)return next(fail(404,'not_found','Resource not found.'));next();}; }
async function member(conn, roomId, userId, lock=false) {
  const [rows]=await conn.execute(`SELECT rm.*, r.host_user_id, r.status AS room_status FROM room_members rm JOIN rooms r ON r.id=rm.room_id WHERE rm.room_id=? AND rm.user_id=? AND rm.membership_status='active' ${lock?'FOR UPDATE':''}`, [roomId,userId]);
  if(!rows.length)throw fail(403,'not_room_member','Join the room first.'); return rows[0];
}
async function gameMember(conn, gameId, userId, lock=false) {
  const [rows]=await conn.execute(`SELECT gp.*,u.username,g.current_phase,g.day_number,g.status AS game_status,g.phase_ends_at,g.phase_started_at,g.winner_team,g.room_id FROM game_players gp JOIN users u ON u.id=gp.user_id JOIN games g ON g.id=gp.game_id WHERE gp.game_id=? AND gp.user_id=? ${lock?'FOR UPDATE':''}`, [gameId,userId]);
  if(!rows.length)throw fail(403,'not_game_member','You are not a player in this game.'); return rows[0];
}
function roomChannel(roomId){return `room:${roomId}`}
function gameChannel(gameId){return `game:${gameId}`}

async function createSession(userId,res) {
  const token=randomBytes(32).toString('base64url'), csrfToken=randomBytes(32).toString('base64url');
  const ttl=Math.min(30,Math.max(1,Number(process.env.SESSION_TTL_DAYS)||14))*24*60*60;
  const expires=addMs(now(),ttl*1000);
  await getPool().execute('INSERT INTO sessions (id,user_id,token_hash,csrf_hash,expires_at) VALUES (?,?,?,?,?)',[id(),userId,hash(token),hash(csrfToken),expires]);
  res.locals.csrfToken=csrfToken;
  setSessionCookie(res,token,ttl); return csrfToken;
}

