app.post('/api/auth/register',authLimiter,body(registerSchema),wrap(async(req,res)=>{
  const {username,email,password}=req.input;
  const passwordHash=await argon2.hash(password,{type:argon2.argon2id,memoryCost:19456,timeCost:2,parallelism:1});
  const userId=id();
  try { await getPool().execute('INSERT INTO users (id,username,email,password_hash) VALUES (?,?,?,?)',[userId,username,email,passwordHash]); }
  catch(e){if(e.code==='ER_DUP_ENTRY')throw fail(409,'account_exists','That username or email is already registered.');throw e;}
  const csrfToken=await createSession(userId,res);res.status(201).json({user:{id:userId,username,email,avatar:'A'},csrfToken});
}));
