app.post('/api/rooms/:roomId/leave',requireAuth,validateParam('roomId'),wrap(async(req,res)=>{await transaction(async tx=>{const m=await member(tx,req.params.roomId,req.user.id,true);if(m.room_status==='in_progress')throw fail(409,'game_running','Leave the match from its results screen.');await tx.execute('UPDATE room_members SET membership_status="left",left_at=UTC_TIMESTAMP(3) WHERE id=?',[m.id]);if(m.host_user_id===req.user.id){const [next]=await tx.execute('SELECT rm.user_id FROM room_members rm JOIN users u ON u.id=rm.user_id WHERE rm.room_id=? AND rm.membership_status="active" AND u.is_bot=FALSE ORDER BY rm.joined_at LIMIT 1',[req.params.roomId]);if(next.length)await tx.execute('UPDATE rooms SET host_user_id=?,revision=revision+1 WHERE id=?',[next[0].user_id,req.params.roomId]);else{await tx.execute('UPDATE rooms SET status="closed",revision=revision+1 WHERE id=?',[req.params.roomId]);await tx.execute('UPDATE room_members rm JOIN users u ON u.id=rm.user_id SET rm.membership_status="left",rm.left_at=UTC_TIMESTAMP(3) WHERE rm.room_id=? AND u.is_bot=TRUE',[req.params.roomId]);}}else await tx.execute('UPDATE rooms SET revision=revision+1 WHERE id=?',[req.params.roomId]);});res.json({ok:true});await publish(roomChannel(req.params.roomId),'room.member_left',{roomId:req.params.roomId,userId:req.user.id});}));
