async function gamePlayers(conn,gameId){const [rows]=await conn.execute('SELECT gp.user_id,u.username,u.avatar,u.is_bot AS isBot,gp.seat_number AS seat,gp.role,gp.team,gp.player_status AS status FROM game_players gp JOIN users u ON u.id=gp.user_id WHERE gp.game_id=? ORDER BY gp.seat_number',[gameId]);return rows;}
function pickBotTarget(candidates){return candidates.length?candidates[Math.floor(Math.random()*candidates.length)]:null;}
async function prepareBots(conn,gameId,roomId,phase,day,players){
  const alive=players.filter(p=>p.status==='alive'),bots=alive.filter(p=>p.isBot);if(!bots.length)return;
  if(phase==='voting'){
    for(const bot of bots){const candidates=alive.filter(p=>p.user_id!==bot.user_id);let targets=candidates;if(bot.team==='mafia')targets=candidates.filter(p=>p.team!=='mafia');else{const mafia=candidates.filter(p=>p.team==='mafia');if(mafia.length&&Math.random()<.28)targets=mafia;}const target=pickBotTarget(targets),[saved]=await conn.execute('INSERT IGNORE INTO votes (id,game_id,day_number,voter_user_id,target_user_id) VALUES (?,?,?,?,?)',[id(),gameId,day,bot.user_id,target?.user_id||null]);if(saved.affectedRows)await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,"voting","vote_cast",?)',[id(),gameId,day,target?`${bot.username} voted for ${target.username}.`:`${bot.username} chose to skip the vote.`]);}
  }else if(phase==='night'){
    const ability={mafia:'mafia_kill',don:'mafia_kill',maniac:'maniac_kill',sheriff:'investigate',detective:'investigate',doctor:'protect',jailor:'detain',prostitute:'block',vagabond:'observe'};
    for(const bot of bots){const actionType=ability[bot.role];if(!actionType)continue;let candidates=alive.filter(p=>p.user_id!==bot.user_id);if(['mafia','don'].includes(bot.role))candidates=candidates.filter(p=>p.team!=='mafia');if(bot.role==='doctor'){const [last]=await conn.execute('SELECT target_user_id FROM game_actions WHERE game_id=? AND actor_user_id=? AND action_type="protect" AND action_status="resolved" ORDER BY day_number DESC LIMIT 1',[gameId,bot.user_id]);candidates=candidates.filter(p=>p.user_id!==last[0]?.target_user_id);if(Math.random()<.2&&bot.user_id!==last[0]?.target_user_id)candidates.push(bot);}if(['sheriff','detective'].includes(bot.role)){const mafia=candidates.filter(p=>p.team==='mafia');if(mafia.length&&Math.random()<.45)candidates=mafia;}const target=pickBotTarget(candidates);if(!target)continue;await conn.execute('INSERT IGNORE INTO game_actions (id,game_id,day_number,phase,actor_user_id,action_type,target_user_id,idempotency_key) VALUES (?,?,?,"night",?,?,?,?)',[id(),gameId,day,bot.user_id,actionType,target.user_id,`bot:${bot.user_id}:night:${day}`]);}
  }else if(phase==='verdict'){
    const [g]=await conn.execute('SELECT verdict_target_user_id FROM games WHERE id=?',[gameId]),accused=g[0]?.verdict_target_user_id;
    const suspect=players.find(p=>p.user_id===accused);if(!suspect)return;
    const mafiaSuspect=suspect.team==='mafia';
    for(const bot of bots)if(bot.user_id!==accused){const convict=Math.random()<(mafiaSuspect?.8:.52);await conn.execute('INSERT IGNORE INTO game_verdict_votes (id,game_id,day_number,voter_user_id,accused_user_id,convict) VALUES (?,?,?,?,?,?)',[id(),gameId,day,bot.user_id,accused,convict]);}
  }else if(phase==='day'){
    const speakers=bots.filter(()=>Math.random()<.55).slice(0,3),lines=['I would like to hear from everyone before the vote.','Something about that last vote feels off.','Let us compare what happened overnight.','I am not sure who to trust yet.'];for(const bot of speakers){const suspect=pickBotTarget(alive.filter(p=>p.user_id!==bot.user_id));const text=suspect&&Math.random()<.4?`I have a bad feeling about ${suspect.username}.` :lines[Math.floor(Math.random()*lines.length)];await conn.execute('INSERT INTO chat_messages (id,room_id,game_id,sender_user_id,channel,message) VALUES (?,?,?, ?,"day",?)',[id(),roomId,gameId,bot.user_id,text]);}
  }
}
