async function finishGame(conn, gameId, roomId, winner) {
  const [[current]]=await conn.execute('SELECT current_phase,day_number FROM games WHERE id=?',[gameId]);await conn.execute('UPDATE games SET status="completed",winner_team=?,ended_at=UTC_TIMESTAMP(3),revision=revision+1 WHERE id=? AND status="in_progress"',[winner,gameId]);await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,?,?,?)',[id(),gameId,current.day_number,['role_reveal','night','day','voting','verdict'].includes(current.current_phase)?current.current_phase:'day','game_won',`${winner==='mafia'?'The Mafia':winner==='solo'?'The Maniac':'The Town'} won the game.`]);
  const ps=await gamePlayers(conn,gameId);for(const p of ps)if(!p.isBot)await conn.execute('INSERT IGNORE INTO match_history (id,game_id,user_id,role,team,result,statistics_json) VALUES (?,?,?,?,?,?,?)',[id(),gameId,p.user_id,p.role,p.team,p.team===winner?'win':'loss',JSON.stringify({seat:p.seat,status:p.status})]);
  await conn.execute('DELETE FROM rooms WHERE id=?',[roomId]);
}
async function earlyAdvanceReady(conn,g,players){
  const alive=players.filter(p=>p.status==='alive');
  if(g.current_phase==='voting'){const [[row]]=await conn.execute('SELECT COUNT(*) AS n FROM votes v JOIN game_players gp ON gp.game_id=v.game_id AND gp.user_id=v.voter_user_id AND gp.player_status="alive" WHERE v.game_id=? AND v.day_number=?',[g.id,g.day_number]);return Number(row.n)>=alive.length;}
  if(g.current_phase==='verdict'){const eligible=alive.filter(p=>p.user_id!==g.verdict_target_user_id);const [[row]]=await conn.execute('SELECT COUNT(*) AS n FROM game_verdict_votes WHERE game_id=? AND day_number=? AND accused_user_id=?',[g.id,g.day_number,g.verdict_target_user_id]);return Number(row.n)>=eligible.length;}
  if(g.current_phase!=='night')return false;
  const [rows]=await conn.execute('SELECT actor_user_id,action_type,target_user_id FROM game_actions WHERE game_id=? AND day_number=? AND phase="night" AND action_status="submitted"',[g.id,g.day_number]);
  const actions=rows.map(a=>({actorUserId:a.actor_user_id,actionType:a.action_type,targetUserId:a.target_user_id}));
  const detained=new Set(actions.filter(a=>a.actionType==='detain').map(a=>a.targetUserId));
  const blocked=new Set([...detained,...actions.filter(a=>a.actionType==='block').map(a=>a.targetUserId)]);
  const hasAction=new Set(actions.map(a=>a.actorUserId));
  const mafia=alive.filter(p=>p.team==='mafia'&&p.role==='don');
  const mandatory=[];
  for(const p of alive){
    const role=p.role;
    if(!['mafia','don','maniac','sheriff','doctor','detective','jailor','prostitute','vagabond'].includes(role)||blocked.has(p.user_id))continue;
    if(role==='mafia'&&mafia.length)continue;
    let candidates=alive.filter(t=>(role==='doctor'||t.user_id!==p.user_id)&&(role!=='mafia'&&role!=='don'||t.team!=='mafia'));
    if(role==='doctor'){const [last]=await conn.execute('SELECT target_user_id FROM game_actions WHERE game_id=? AND actor_user_id=? AND action_type="protect" AND action_status="resolved" ORDER BY day_number DESC LIMIT 1',[g.id,p.user_id]);candidates=candidates.filter(t=>t.user_id!==last[0]?.target_user_id)}
    if(candidates.length)mandatory.push(p);
  }
  return mandatory.every(p=>hasAction.has(p.user_id));
}
async function advanceGame(gameId, actorId=null, job=false, automatic=false) {
  return transaction(async conn=>{
    const [gs]=await conn.execute('SELECT * FROM games WHERE id=? FOR UPDATE',[gameId]);if(!gs.length)throw fail(404,'not_found','Game not found.');const g=gs[0];if(g.status!=='in_progress')return {completed:true,gameId};
    if(!job){const m=await member(conn,g.room_id,actorId);if(m.host_user_id!==actorId)throw fail(403,'host_only','Only the host may advance a phase.');}
    const ps=await gamePlayers(conn,gameId),deadlinePassed=new Date(g.phase_ends_at)<=now();if(!deadlinePassed&&(!automatic||!(await earlyAdvanceReady(conn,g,ps)))){if(automatic)return {noChange:true,gameId};throw fail(409,'phase_active','The phase deadline has not passed.');}
    let eliminated=null,eliminatedUserIds=[],investigations=[],observations=[];let phase,day=g.day_number;
    if(g.current_phase==='role_reveal'){phase='night';}
    else if(g.current_phase==='day'){phase='voting';}
    else if(g.current_phase==='voting'){
      const [votes]=await conn.execute('SELECT voter_user_id AS voterUserId,target_user_id AS targetUserId FROM votes WHERE game_id=? AND day_number=?',[gameId,g.day_number]);const counted=countVotes(votes,ps.filter(p=>p.status==='alive').map(p=>p.user_id));eliminated=counted.eliminatedUserId;
      if(eliminated){const votedOut=ps.find(p=>p.user_id===eliminated);await conn.execute('UPDATE games SET verdict_target_user_id=? WHERE id=?',[eliminated,gameId]);await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,"verdict",?,?)',[id(),gameId,day,'verdict_open',`${votedOut?.username||'A player'} has been accused. The town must decide: convict or spare?`]);phase='verdict';}
      else {const type=counted.tied?'vote_tie':counted.skipWon?'vote_skipped':'vote_empty',message=counted.tied?'The vote was tied. Nobody was nominated.':counted.skipWon?'The town chose to skip. Nobody was nominated.':'No votes were cast. Nobody was nominated.';await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,"voting",?,?)',[id(),gameId,day,type,message]);phase='night';day++;}
    } else if(g.current_phase==='verdict'){
      const [ballots]=await conn.execute('SELECT convict FROM game_verdict_votes WHERE game_id=? AND day_number=? AND accused_user_id=?',[gameId,day,g.verdict_target_user_id]);const convict=ballots.filter(v=>!!v.convict).length,spare=ballots.length-convict;eliminated=convict>spare?g.verdict_target_user_id:null;
      if(eliminated)await conn.execute('UPDATE game_players SET player_status="eliminated",eliminated_at=UTC_TIMESTAMP(3) WHERE game_id=? AND user_id=? AND player_status="alive"',[gameId,eliminated]);
      const accused=ps.find(p=>p.user_id===g.verdict_target_user_id),message=eliminated?`${accused?.username||'The accused'} was convicted and eliminated.`:`${accused?.username||'The accused'} was spared and remains in the game.`;await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,"verdict",?,?)',[id(),gameId,day,eliminated?'verdict_convicted':'verdict_spared',message]);
      await conn.execute('UPDATE games SET verdict_target_user_id=NULL WHERE id=?',[gameId]);const after=ps.map(p=>p.user_id===eliminated?{...p,status:'eliminated'}:p),winner=getWinner(after);if(winner){await finishGame(conn,gameId,g.room_id,winner);return {gameId,phase:'completed',dayNumber:day,winner,eliminatedUserId:eliminated};}phase='night';day++;
    } else {
      const [acts]=await conn.execute('SELECT actor_user_id AS actorUserId,action_type AS actionType,target_user_id AS targetUserId FROM game_actions WHERE game_id=? AND day_number=? AND phase="night" AND action_status="submitted" ORDER BY CASE action_type WHEN "detain" THEN 1 WHEN "block" THEN 1 WHEN "protect" THEN 2 WHEN "investigate" THEN 3 WHEN "observe" THEN 4 WHEN "mafia_kill" THEN 5 WHEN "maniac_kill" THEN 5 ELSE 6 END,created_at',[gameId,g.day_number]);const resolved=resolveNightActions(acts,ps.map(p=>({userId:p.user_id,username:p.username,role:p.role,team:p.team,status:p.status})));eliminatedUserIds=resolved.eliminatedUserIds;eliminated=resolved.eliminatedUserId;investigations=resolved.investigations;observations=resolved.observations;
      for(const item of investigations)await conn.execute('INSERT INTO game_role_results (id,game_id,user_id,day_number,result_type,result_json) VALUES (?,?,?,? ,"investigation",?)',[id(),gameId,item.actorUserId,day,JSON.stringify({targetUserId:item.targetUserId,targetUsername:item.targetUsername,result:item.result})]);for(const item of observations)await conn.execute('INSERT INTO game_role_results (id,game_id,user_id,day_number,result_type,result_json) VALUES (?,?,?,? ,"observation",?)',[id(),gameId,item.actorUserId,day,JSON.stringify({targetUserId:item.targetUserId,targetUsername:item.targetUsername,visitors:item.visitors})]);for(const item of resolved.blockResults)await conn.execute('INSERT INTO game_role_results (id,game_id,user_id,day_number,result_type,result_json) VALUES (?,?,?,? ,"block",?)',[id(),gameId,item.actorUserId,day,JSON.stringify({targetUserId:item.targetUserId,targetUsername:item.targetUsername,executed:item.executed,blocked:item.blocked})]);
      for(const victim of eliminatedUserIds)await conn.execute('UPDATE game_players SET player_status="eliminated",eliminated_at=UTC_TIMESTAMP(3) WHERE game_id=? AND user_id=? AND player_status="alive"',[gameId,victim]);await conn.execute('UPDATE game_actions SET action_status="resolved" WHERE game_id=? AND day_number=? AND phase="night"',[gameId,g.day_number]);
      const nightMessage=eliminatedUserIds.length?`${eliminatedUserIds.map(uid=>ps.find(p=>p.user_id===uid)?.username||'A player').join(' and ')} were found eliminated this morning.`:'Nobody was eliminated during the night.';await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,"night",?,?)',[id(),gameId,day,eliminatedUserIds.length?'night_elimination':'night_safe',nightMessage]);
      const after=ps.map(p=>eliminatedUserIds.includes(p.user_id)?{...p,status:'eliminated'}:p),winner=getWinner(after);if(winner){await finishGame(conn,gameId,g.room_id,winner);return {gameId,phase:'completed',dayNumber:day,winner,eliminatedUserId:eliminated,eliminatedUserIds,privateInvestigations:investigations,privateObservations:observations};}phase='day';
    }
    if(phase==='night')await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,"night","city_sleeps","The city falls asleep. Night actions are now locked in.")',[id(),gameId,day]);if(phase==='voting')await conn.execute('INSERT INTO game_events (id,game_id,day_number,phase,event_type,public_message) VALUES (?,?,?,"voting","voting_open","Discussion is over. Voting is now open.")',[id(),gameId,day]);
    const [[roomSettingsRow]]=await conn.execute('SELECT settings_json FROM rooms WHERE id=?',[g.room_id]);const settings=typeof roomSettingsRow.settings_json==='string'?JSON.parse(roomSettingsRow.settings_json):roomSettingsRow.settings_json;const started=now(),duration=phase==='voting'||phase==='verdict'?Number(settings.voteSeconds||30)*1000:phase==='night'?Number(settings.nightSeconds||60)*1000:Math.min(60,Number(settings.daySeconds||60))*1000,ends=addMs(started,duration);await conn.execute('UPDATE games SET current_phase=?,day_number=?,phase_started_at=?,phase_ends_at=?,revision=revision+1 WHERE id=? AND status="in_progress"',[phase,day,started,ends,gameId]);await conn.execute('UPDATE rooms SET revision=revision+1 WHERE id=?',[g.room_id]);await prepareBots(conn,gameId,g.room_id,phase,day,await gamePlayers(conn,gameId));return {gameId,roomId:g.room_id,phase,dayNumber:day,phaseStartedAt:started,phaseEndsAt:ends,eliminatedUserId:eliminated,eliminatedUserIds,privateInvestigations:investigations,privateObservations:observations};
  });
}
async function publishTransition(gameId,result){const {privateInvestigations=[],privateObservations=[],...publicResult}=result;await publish(gameChannel(gameId),result.phase==='completed'?'game.results':'game.phase_changed',publicResult);const eliminated=[...(result.eliminatedUserIds||[])];if(!eliminated.length&&result.eliminatedUserId)eliminated.push(result.eliminatedUserId);for(const userId of eliminated)await publish(gameChannel(gameId),'game.player_eliminated',{userId,phase:result.phase});for(const item of privateInvestigations)await publish(`user:${item.actorUserId}`,'game.investigation_result',{gameId,targetUserId:item.targetUserId,result:item.result});for(const item of privateObservations)await publish(`user:${item.actorUserId}`,'game.role_result',{gameId,role:'vagabond',targetUserId:item.targetUserId,visitors:item.visitors});return publicResult;}
export async function advanceExpiredGames(){const [expired]=await getPool().execute('SELECT id FROM games WHERE status="in_progress" AND phase_ends_at<=UTC_TIMESTAMP(3) ORDER BY phase_ends_at LIMIT 50');const results=[];for(const game of expired){try{const result=await advanceGame(game.id,null,true,true);if(!result.noChange)results.push(await publishTransition(game.id,result));}catch(error){console.error('phase_reconcile_failed',{gameId:game.id,code:error.code||error.message});}}return results;}
