export async function deleteInactiveWaitingRooms(){const [orphanedGames]=await getPool().execute(`UPDATE games g JOIN rooms r ON r.id=g.room_id SET g.status='cancelled',g.ended_at=UTC_TIMESTAMP(3) WHERE g.status='in_progress' AND NOT EXISTS (SELECT 1 FROM room_members rm JOIN users u ON u.id=rm.user_id WHERE rm.room_id=r.id AND rm.membership_status='active' AND u.is_bot=FALSE AND COALESCE(rm.last_seen_at,rm.joined_at)>=DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 2 MINUTE))`);const [deleted]=await getPool().execute(`DELETE r FROM rooms r WHERE (r.status='waiting' AND (r.created_at<DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 10 MINUTE) OR NOT EXISTS (SELECT 1 FROM room_members rm JOIN users u ON u.id=rm.user_id WHERE rm.room_id=r.id AND rm.membership_status='active' AND u.is_bot=FALSE AND COALESCE(rm.last_seen_at,rm.joined_at)>=DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 2 MINUTE))) OR (r.status='in_progress' AND NOT EXISTS (SELECT 1 FROM room_members rm JOIN users u ON u.id=rm.user_id WHERE rm.room_id=r.id AND rm.membership_status='active' AND u.is_bot=FALSE AND COALESCE(rm.last_seen_at,rm.joined_at)>=DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 2 MINUTE))) OR r.status='closed')`);await getPool().execute('DELETE u FROM users u WHERE u.is_bot=TRUE AND NOT EXISTS (SELECT 1 FROM room_members rm WHERE rm.user_id=u.id) AND NOT EXISTS (SELECT 1 FROM game_players gp WHERE gp.user_id=u.id)');return deleted.affectedRows+orphanedGames.affectedRows;}
